package com.powerliq.valuation;import com.powerliq.valuation.ValuationModels.*;import java.net.URI;import java.util.UUID;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v2/valuations")public class ValuationController{private final ValuationApplicationService service;public ValuationController(ValuationApplicationService s){service=s;}@PostMapping public ResponseEntity<Result> calculate(@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Request request){Result r=service.calculate(key,request);return ResponseEntity.created(URI.create("/api/v2/valuations/"+r.id())).body(r);}@GetMapping("/{id}")public Result find(@PathVariable UUID id){return service.find(id);}}
